       --muted: #5b6678;
       --border: #d8e0ee;
       --accent: #4f7cff;
       --accent-strong: #315ee8;
       --accent-soft: rgba(79, 124, 255, 0.12);
       --shadow: 0 24px 60px rgba(24, 33, 47, 0.12);
       --radius: 24px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, rgba(79, 124, 255, 0.18), transparent 32%),
         radial-gradient(circle at bottom right, rgba(109, 230, 201, 0.2), transparent 30%),
         var(--bg);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .card {
       width: min(100%, 560px);
       background: var(--panel);
       backdrop-filter: blur(16px);
       border: 1px solid rgba(255, 255, 255, 0.65);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       padding: 32px;
     }

     .eyebrow {
       margin: 0 0 10px;
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0 0 10px;
