     }

     .intro {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 24px;
     }

     .form-field {
       border: 1px solid var(--border);
       border-radius: 20px;
       padding: 22px;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.9), rgba(244, 247, 251, 0.9));
     }

     fieldset {
       border: 0;
       margin: 0;
       padding: 0;
       min-width: 0;
     }

     legend {
       padding: 0;
       margin-bottom: 16px;
       font-size: 1.05rem;
       font-weight: 700;
     }

     .option-list {
       display: grid;
       gap: 12px;
     }

