       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 16px 30px rgba(49, 94, 232, 0.24);
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.03);
     }

     button:active {
       transform: translateY(0);
