   <main class="card">
     <p class="eyebrow">Preferences</p>
     <h1>Choose your notification method</h1>
     <p class="intro">Tell us how you prefer to receive updates so we can keep your experience personalized.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>
           <div class="option-list">
             <label class="option">
               <input type="radio" name="notificationPreference" value="Email" required>
               <span class="option-title">Email</span>
             </label>

             <label class="option">
               <input type="radio" name="notificationPreference" value="SMS">
               <span class="option-title">SMS</span>
             </label>

             <label class="option">
               <input type="radio" name="notificationPreference" value="Push Notifications">
               <span class="option-title">Push Notifications</span>
             </label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit</button>
       <p class="message" id="form-message" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const message = document.getElementById("form-message");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const selection = new FormData(form).get("notificationPreference");
       message.textContent = "Preference saved: " + selection + ".";
     });
   </script>
